13	#[derive(Clone, Default, Debug)]
14	pub struct CommentMap(pub BTreeMap<ByteSpan, Comment>);
15	
16	impl Deref for CommentMap {
17	    type Target = BTreeMap<ByteSpan, Comment>;
18	
19	    fn deref(&self) -> &BTreeMap<ByteSpan, Comment> {
20	        &self.0
21	    }
22	}
23	
24	impl DerefMut for CommentMap {
25	    fn deref_mut(&mut self) -> &mut Self::Target {
26	        &mut self.0
27	    }
28	}
