30	impl CommentMap {
31	    pub fn new() -> Self {
32	        Self(BTreeMap::new())
33	    }
34	
35	    /// Get the CommentedTokenStream and collect the spans -> Comment mapping for the input source
36	    /// code.
37	    pub fn from_src(input: Source) -> Result<Self, FormatterError> {
38	        // Pass the input through the lexer.
39	        let tts = lex(input)?;
40	        let tts = tts.token_trees().iter();
41	
42	        let mut comment_map = CommentMap::new();
43	        for comment in tts {
44	            comment_map.collect_comments_from_token_stream(comment);
45	        }
46	        Ok(comment_map)
47	    }
48	
49	    /// Given a range, return an iterator to comments contained within the range.
50	    pub fn comments_between<'a>(
51	        &'a self,
52	        range: &'a Range<usize>,
53	    ) -> impl Iterator<Item = &'a Comment> {
54	        self.iter().filter_map(|(bs, c)| {
55	            if bs.contained_within(range) {
56	                Some(c)
57	            } else {
58	                None
59	            }
60	        })
61	    }
62	
63	    /// Collects `Comment`s from the token stream and insert it with its span to the `CommentMap`.
64	    /// Handles both the standalone and in-block comments.
65	    fn collect_comments_from_token_stream(&mut self, commented_token_tree: &CommentedTokenTree) {
66	        match commented_token_tree {
67	            CommentedTokenTree::Comment(comment) => {
68	                let comment_span = ByteSpan {
69	                    start: comment.span.start(),
70	                    end: comment.span.end(),
71	                };
72	                self.insert(comment_span, comment.clone());
73	            }
74	            CommentedTokenTree::Tree(CommentedTree::Group(group)) => {
75	                for item in group.token_stream.token_trees().iter() {
76	                    self.collect_comments_from_token_stream(item);
77	                }
78	            }
79	            _ => {}
80	        }
81	    }
82	}
83	
84	trait CommentRange {
85	    /// Get comments in between given ByteSpans. This is wrapper around BtreeMap::range with a custom logic for beginning of the file.
86	    fn comments_in_range(&self, from: &ByteSpan, to: &ByteSpan) -> Vec<(ByteSpan, Comment)>;
87	}
88	
89	impl CommentRange for CommentMap {
90	    fn comments_in_range(&self, from: &ByteSpan, to: &ByteSpan) -> Vec<(ByteSpan, Comment)> {
91	        // While searching for comments with given range, comment handler needs to check if the beginning of the range is actually the beginning of the file.
92	        // If that is the case we need to collect all the comments until the provided `to` ByteSpan. BtreeMap::range((Inclusive(from), Excluded(to))) won't be able to find comments
93	        // since both beginning of the file and first byte span have their start = 0. If we are looking from STARTING_BYTE_SPAN to `to`, we need to collect all until `to` byte span.
94	        if from == &byte_span::STARTING_BYTE_SPAN {
95	            self.range(..to)
96	                .map(|(byte_span, comment)| (byte_span.clone(), comment.clone()))
97	                .collect()
98	        } else {
99	            self.range((Included(from), Excluded(to)))
100	                .map(|(byte_span, comment)| (byte_span.clone(), comment.clone()))
101	                .collect()
102	        }
103	    }
104	}
