66	/// Writes a trailing comment using potentially destructive 'truncate()' to strip the end
67	/// of whitespaces.
68	fn write_trailing_comment(
69	    formatted_code: &mut FormattedCode,
70	    comment: &Comment,
71	) -> Result<(), FormatterError> {
72	    formatted_code.truncate(formatted_code.trim_end().len());
73	    writeln!(formatted_code, " {}", comment.span().as_str().trim_end())?;
74	
75	    Ok(())
76	}
